ALTER TABLE "Order" ADD COLUMN "sourceKind" TEXT NOT NULL DEFAULT 'CART', ADD COLUMN "sourceRef" TEXT;
CREATE UNIQUE INDEX "Order_sourceRef_key" ON "Order"("sourceRef");
ALTER TABLE "Coupon" ADD COLUMN "ownerId" TEXT REFERENCES "User"("id") ON DELETE CASCADE, ADD COLUMN "singleUse" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "claimedOrderId" TEXT REFERENCES "Order"("id") ON DELETE SET NULL;
CREATE UNIQUE INDEX "Coupon_claimedOrderId_key" ON "Coupon"("claimedOrderId");
CREATE TABLE "BusinessProfile" ("userId" TEXT PRIMARY KEY REFERENCES "User"("id") ON DELETE CASCADE,"legalName" TEXT NOT NULL,"registrationNumber" TEXT NOT NULL,"billingAddress" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING' CHECK ("status" IN ('PENDING','APPROVED','REJECTED')),"reviewNote" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "WholesaleTier" ("id" TEXT PRIMARY KEY,"variantId" TEXT NOT NULL REFERENCES "ProductVariant"("id") ON DELETE CASCADE,"minQty" INTEGER NOT NULL CHECK ("minQty" BETWEEN 2 AND 999),"unitPriceMinor" INTEGER NOT NULL CHECK ("unitPriceMinor">0));
CREATE UNIQUE INDEX "WholesaleTier_variantId_minQty_key" ON "WholesaleTier"("variantId","minQty");
CREATE TABLE "QuoteRequest" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"variantId" TEXT NOT NULL REFERENCES "ProductVariant"("id"),"qty" INTEGER NOT NULL CHECK ("qty" BETWEEN 2 AND 999),"note" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'REQUESTED' CHECK ("status" IN ('REQUESTED','OFFERED','ACCEPTED','CONSUMED','DECLINED')),"unitPriceMinor" INTEGER CHECK ("unitPriceMinor">0),"sellerNote" TEXT,"expiresAt" TIMESTAMP(3),"orderId" TEXT REFERENCES "Order"("id") ON DELETE SET NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "QuoteRequest_orderId_key" ON "QuoteRequest"("orderId");
CREATE INDEX "QuoteRequest_userId_status_idx" ON "QuoteRequest"("userId","status");
CREATE TABLE "Subscription" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"variantId" TEXT NOT NULL REFERENCES "ProductVariant"("id"),"qty" INTEGER NOT NULL CHECK ("qty" BETWEEN 1 AND 99),"intervalDays" INTEGER NOT NULL CHECK ("intervalDays" IN (14,30,60,90)),"status" TEXT NOT NULL DEFAULT 'ACTIVE' CHECK ("status" IN ('ACTIVE','PAUSED','CANCELLED')),"nextAt" TIMESTAMP(3) NOT NULL,"cycle" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Subscription_status_nextAt_idx" ON "Subscription"("status","nextAt");
CREATE TABLE "SubscriptionRenewal" ("id" TEXT PRIMARY KEY,"subscriptionId" TEXT NOT NULL REFERENCES "Subscription"("id") ON DELETE CASCADE,"cycle" INTEGER NOT NULL,"dueAt" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'DUE' CHECK ("status" IN ('DUE','ORDERED','SKIPPED')),"orderId" TEXT REFERENCES "Order"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "SubscriptionRenewal_orderId_key" ON "SubscriptionRenewal"("orderId");
CREATE UNIQUE INDEX "SubscriptionRenewal_subscriptionId_cycle_key" ON "SubscriptionRenewal"("subscriptionId","cycle");
CREATE TABLE "RewardEntry" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"orderId" TEXT REFERENCES "Order"("id") ON DELETE SET NULL,"points" INTEGER NOT NULL,"type" TEXT NOT NULL,"ref" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "RewardEntry_ref_key" ON "RewardEntry"("ref");
CREATE INDEX "RewardEntry_userId_createdAt_idx" ON "RewardEntry"("userId","createdAt");
CREATE TABLE "ReferralProfile" ("userId" TEXT PRIMARY KEY REFERENCES "User"("id") ON DELETE CASCADE,"code" TEXT NOT NULL UNIQUE);
CREATE TABLE "Referral" ("id" TEXT PRIMARY KEY,"referrerId" TEXT NOT NULL REFERENCES "User"("id"),"inviteeId" TEXT NOT NULL UNIQUE REFERENCES "User"("id"),"status" TEXT NOT NULL DEFAULT 'CLAIMED',"orderId" TEXT UNIQUE REFERENCES "Order"("id") ON DELETE SET NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK ("referrerId"<>"inviteeId"));
CREATE TABLE "MarketingSubscriber" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"userId" TEXT REFERENCES "User"("id") ON DELETE SET NULL,"status" TEXT NOT NULL DEFAULT 'PENDING' CHECK ("status" IN ('PENDING','CONFIRMED','UNSUBSCRIBED')),"tokenHash" TEXT NOT NULL UNIQUE,"tokenCipher" TEXT NOT NULL,"confirmationExpiresAt" TIMESTAMP(3),"consentAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"confirmedAt" TIMESTAMP(3));
CREATE INDEX "MarketingSubscriber_status_id_idx" ON "MarketingSubscriber"("status","id");
CREATE TABLE "Campaign" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"audience" TEXT NOT NULL DEFAULT 'ALL',"status" TEXT NOT NULL DEFAULT 'DRAFT',"scheduledAt" TIMESTAMP(3),"cursor" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Campaign_status_scheduledAt_idx" ON "Campaign"("status","scheduledAt");
ALTER TABLE "OutboxEvent" ADD COLUMN "campaignId" TEXT REFERENCES "Campaign"("id") ON DELETE SET NULL;
CREATE INDEX "OutboxEvent_campaignId_idx" ON "OutboxEvent"("campaignId");
